POINT_TYPES = {
    1: ('LDI', 'Logical Digital Input', -1),
    2: ('LDO', 'Logical Digital Output', -2),
    3: ('LAI', 'Logical Analog Input', None),
    4: ('LAO', 'Logical Analog Output', None),
    6: ('L2SL', 'Logical Two-State Latched', -6),
    7: ('LOOAP', 'Logical On/Off/Auto Pulsed', -7),
    11: ('LPACI', 'Logical Pulse Accumulator (Counter) Input', None),
    12: ('L2SP', 'Logical Two-State Pulsed', -12),
    13: ('LOOAL', 'Logical On/Off/Auto Latched', -13),
    14: ('LFSSL', 'Logical Fast/Slow/Stop Latched', -14),
    15: ('LFSSP', 'Logical Fast/Slow/Stop Pulsed', -15),
    19: ('LCTLR', 'Logical Controller (control loop)', -19),
    20: ('LDAO', 'Logical Digital-Actuated Analog Output', None),
    21: ('LENUM', 'Logical Enumerated (multistate)', -21),
    22: ('LFMSSL', 'Logical Fast/Medium/Slow/Stop Latched', None),
    23: ('LFMSSP', 'Logical Fast/Medium/Slow/Stop Pulsed', None),
    24: ('PPCL_LAI', 'PPCL-referenced analog input', None),
}


def default_enum_for(point_type):
    """Enum id of a type's default state-text set, or None.

    It is the negation of the type code. Analog types have none.
    """
    t = POINT_TYPES.get(point_type)
    return t[2] if t else None


def point_type_name(point_type):
    """Mnemonic for a type code (LDI, LAO, ...), or None."""
    t = POINT_TYPES.get(point_type)
    return t[0] if t else None


def enum_name(enum_id, value):
    """Resolve a point state. Returns None if unknown."""
    t = ENUM_TYPES.get(enum_id)
    return t[2].get(value) if t else None


def resolve_state_text(value, point_type=None, enum_id=None):
    """Render an enumerated point value as text, or None.

    `enum_id` is the point's explicit enumeration if it carries one.
    When it does not, the point type's DEFAULT enumeration applies.
    Analog types have none and return None, which is correct: an
    analog point has no enumerated states.
    """
    eid = enum_id if enum_id is not None else default_enum_for(point_type)
    if eid is None:
        return None
    try:
        v = int(round(float(value)))
    except (TypeError, ValueError):
        return None
    return enum_name(eid, v)


def revision(rev_string):
    """(level, cabinet type, ASCII|RAD50) for a revision string."""
    return REVISIONS.get(rev_string)
